BEGIN;

DO $$ 
DECLARE
    v_topic_id UUID;
BEGIN
    -- Fetch the topic ID (using both possible slugs as fallbacks)
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'clinical-reasoning-diagnosis' LIMIT 1;
    IF v_topic_id IS NULL THEN
        SELECT id INTO v_topic_id FROM topics WHERE slug = 'clinical-reasoning-differential' LIMIT 1;
    END IF;

    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic not found for slug clinical-reasoning-diagnosis or clinical-reasoning-differential';
    END IF;

    -- Idempotent Insert for MCQs (Batch 3: 551-650)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation)
    SELECT v_topic_id, t.question, t.options, t.correct_index, t.explanation
    FROM (VALUES
        ('In an "On Call" setting, what is the first reasoning priority when called about a "sick" patient?', '["Finding the final diagnosis", "Assessing the ABCs and immediate stability", "Ordering a complete lab panel", "Calling the attending"]'::jsonb, 1, 'The immediate goal is to recognize and stabilize life-threatening instability before pursuing a definitive diagnosis.'),
        ('Which "On Call" symptom in a patient with a "fever" should trigger the highest concern for sepsis?', '["A temperature of 103F", "Confusion or Hypotension", "Cough", "A white blood cell count of 12,000"]'::jsonb, 1, 'End-organ dysfunction (confusion) and hemodynamic instability (hypotension) are the hallmarks of septic shock.'),
        ('A patient with "oliguria" (low urine output) who has a high BUN/Creatinine ratio (>20:1) and low urine sodium (<20) is in which state?', '["Intrinsically damaged kidney (ATN)", "Prerenal azotemia (dehydration/hypoperfusion)", "Post-renal obstruction", "Normal variant"]'::jsonb, 1, 'The high ratio and low urine sodium show the kidney is still trying to conserve volume, indicating it is healthy but under-perfused.'),
        ('According to the "On Call" protocol, a patient with new-onset "shortness of breath" and "hypotension" should be evaluated first for which \"must-not-miss\" condition?', '["Pneumonia", "Tension Pneumothorax or Massive PE", "COPD flare", "Pleural effusion"]'::jsonb, 1, 'The combination of respiratory distress and shock suggests a mechanical/obstructive problem like tension PTX or a massive clot.'),
        ('Which finding on a lab panel is the most specific for "chronic" alcohol abuse rather than acute ingestion?', '["Elevated AST/ALT ratio > 2:1", "Elevated GGT and Macrocytosis (high MCV)", "High Blood Alcohol Content", "Low blood sugar"]'::jsonb, 1, 'Chronic alcohol use leads to GGT elevation and direct marrow toxicity causing a macrocytic anemia.'),
        ('A patient with "anemia," "thrombocytopenia," and "leukopenia" (pancytopenia) should have which procedure in their reasoning workup?', '["CT abdomen", "Bone marrow biopsy", "Repeat CBC in 1 month", "Serum iron levels"]'::jsonb, 1, 'Pancytopenia suggests the problem is in the \"factory\" (marrow) and needs direct investigation.'),
        ('Which cognitive bias involves the clinician "ignoring" a patient''s symptom because it is inconvenient or would require a complex workup?', '["Commission bias", "Omission bias", "Anchoring", "Sunk cost"]'::jsonb, 1, 'The tendency to NOT act (omission) even when action is indicated.'),
        ('A patient with "fever," "joint pain," and a "new heart murmur" likely has:', '["Rheumatoid arthritis", "Acute Rheumatic Fever or Infective Endocarditis", "Systemic Lupus", "Gout"]'::jsonb, 1, 'These are the major components of Jones Criteria and signs of valvular infection.'),
        ('According to "Bates," which physical exam finding has the highest specificity for "Consolidation" (e.g., Pneumonia)?', '["Dullness to percussion", "Increased tactile fremitus and Egophony", "Decreased breath sounds", "Wheezing"]'::jsonb, 1, 'Solid lung tissue transmits voice sounds (Egophony: \"E\" to \"A\") better than air-filled lung.'),
        ('Which cognitive bias involves the clinician "stopping" the diagnostic process after finding one abnormality, potentially missing a second, more serious one?', '["Anchoring", "Search satisficing", "Confirmation bias", "Availability bias"]'::jsonb, 1, 'A common error in radiology (e.g., seeing one fracture and missing the second).'),
        ('A patient with "high calcium," "low PTH," and "weight loss" likely has:', '["Primary hyperparathyroidism", "Hypercalcemia of malignancy", "Vitamin D intoxication", "Sarcoidosis"]'::jsonb, 1, 'Malignancy is the most common cause of non-PTH mediated hypercalcemia in adults.'),
        ('Which \"On Call\" finding is most concerning in a patient with \"chest pain\"?', '["A \"tearing\" sensation radiating to the back", "Pain that is worse with inspiration", "Reproduction of pain by pressing on the ribs", "Relief with antacids"]'::jsonb, 0, 'Tearing pain suggests aortic dissection, a surgical emergency.'),
        ('According to the "ABCDE" approach, what is the priority for a patient with a "blocked" airway?', '["IV fluids", "Airway maneuvers (e.g., head-tilt/chin-lift) or advanced airway management", "Chest X-ray", "Checking the pupils"]'::jsonb, 1, 'Airway always comes first in the stability assessment.'),
        ('A patient with "hypoxia" that does NOT improve with "100% oxygen" is suffering from a:', '["V/Q mismatch", "True Shunt (e.g., alveolar collapse or right-to-left cardiac shunt)", "Anemia", "Hypoventilation"]'::jsonb, 1, 'If the air cannot reach the blood at all (shunt), increasing the oxygen concentration won''t help.'),
        ('Which cognitive bias involves the clinician being influenced by "who" the patient is (e.g., stereotyping)?', '["Availability bias", "Representative bias", "Affective bias", "Framing effect"]'::jsonb, 2, 'Personal feelings and stereotypes about a patient can cloud diagnostic judgment.'),
        ('A patient with "polyuria," "thirst," and "hypernatremia" whose urine becomes concentrated after "desmopressin" (ADH) has:', '["Central Diabetes Insipidus", "Nephrogenic Diabetes Insipidus", "Primary Polydipsia", "SIADH"]'::jsonb, 0, 'Central DI is a lack of ADH production; the kidneys respond when ADH is replaced.'),
        ('Which \"On Call\" priority is highest for a patient with a \"new\" neurological deficit?', '["Ordering an MRI", "Checking a \"fingerstick\" glucose and ruling out a stroke with a CT", "Ordering a psych consult", "Starting aspirin"]'::jsonb, 1, 'Hypoglycemia can mimic stroke and is rapidly reversible; a CT is needed to rule out hemorrhage.'),
        ('A "positive" Murphy''s sign in a patient with RUQ pain points toward:', '["Appendicitis", "Acute Cholecystitis", "Pancreatitis", "Hepatitis"]'::jsonb, 1, 'Arrest of inspiration on palpation of the gallbladder is highly specific.'),
        ('Which cognitive bias involves the clinician being overly influenced by the "outcome" of a case, rather than the quality of the reasoning at the time?', '["Hindsight bias", "Outcome bias", "Confirmation bias", "Availability bias"]'::jsonb, 1, 'Judging a decision as \"bad\" just because the result was poor, even if the logic was sound based on the data available.'),
        ('A patient with "hemoptysis" and a "new" pulmonary nodule on CXR needs which reasoning next step?', '["Repeat CXR in 1 year", "CT Chest and potential biopsy to rule out malignancy", "Course of antibiotics", "No follow-up needed"]'::jsonb, 1, 'Constitutional symptoms or focal findings in a smoker/elderly patient require aggressive workup for cancer.'),
        ('Which reasoning framework focuses on \"Must-Not-Miss\" conditions that will kill the patient in the next 24 hours?', '["Chronological reasoning", "The \"On Call\" approach", "Pathophysiological reasoning", "Anatomical reasoning"]'::jsonb, 1, 'The \"On Call\" approach prioritizes urgency over diagnostic elegance.'),
        ('A patient with "chronic" microcytic anemia and a "normal" RDW (Red Cell Distribution Width) is more likely to have:', '["Iron deficiency", "Thalassemia trait", "Acute blood loss", "Lead poisoning"]'::jsonb, 1, 'In Thalassemia, all cells are uniformly small (low RDW); in Iron deficiency, there is more variation as the iron runs out (high RDW).'),
        ('Which cognitive bias involves judging a patient''s "non-compliance" as a personality flaw rather than considering situational factors (e.g., poverty)?', '["Fundamental attribution error", "Confirmation bias", "Outcome bias", "Anchoring"]'::jsonb, 0, 'This is a common bias in how clinicians view \"difficult\" patients.'),
        ('On a lab panel, a patient with "high calcium" and "low phosphorus" likely has:', '["Renal failure", "Primary Hyperparathyroidism", "Vitamin D deficiency", "Bone metastasis"]'::jsonb, 1, 'PTH causes the kidney to dump phosphorus and reabsorb calcium.'),
        ('Which \"must-not-miss\" cause of acute \"back pain\" should be ruled out in an elderly patient with a history of HTN?', '["Muscle strain", "Abdominal Aortic Aneurysm (AAA) rupture", "Herniated disc", "Osteoarthritis"]'::jsonb, 1, 'Rupturing AAA can present as severe back or flank pain and is a medical emergency.'),
        ('According to the "SNOOP" mnemonic for headache red flags, what does the "O" stand for?', '["Onset (Sudden/Thunderclap)", "Old age (> 50)", "Oxygen saturation", "Ordering labs"]'::jsonb, 0, 'Sudden onset is a major red flag for intracranial hemorrhage.'),
        ('In clinical reasoning, \"System 2\" thinking is often described as \"metacognitive.\" What does this mean?', '["It is very fast", "It involves thinking about the thinking process itself", "It uses emotions", "It relies on intuition"]'::jsonb, 1, 'Metacognition allows a clinician to consciously monitor their reasoning for errors and biases.'),
        ('A patient with "chronic" abdominal pain that is "relieved by defecation" likely has:', '["Colon cancer", "Irritable Bowel Syndrome (IBS)", "Celiac disease", "Pancreatitis"]'::jsonb, 1, 'Pain relief after BM is a core component of the Rome criteria for IBS.'),
        ('Which lab test is the most important "initial" step for an elderly patient with new-onset confusion (Delirium)?', '["Brain MRI", "Urinalysis and Fingerstick Glucose", "Lumbar puncture", "Liver biopsy"]'::jsonb, 1, 'UTIs and hypoglycemia/hyperglycemia are extremely common causes of delirium in the elderly.'),
        ('According to "Learning Radiology," a \"wedge-shaped\" opacity on a peripheral lung field in a patient with pleuritic pain is:', '["Pneumonia", "Hampton''s Hump (Pulmonary Infarction from PE)", "Lung cancer", "Atelectasis"]'::jsonb, 1, 'This is a classic sign of pulmonary infarction following a pulmonary embolism.'),
        ('Which cognitive bias involves a clinician being influenced by a "recent" case of a rare disease and over-diagnosing it in subsequent patients?', '["Confirmation bias", "Availability bias", "Anchoring", "Sunk cost"]'::jsonb, 1, 'Recent memory makes the diagnosis seem more \"available.\"'),
        ('A patient with "chest pain" and "ST-elevation" in leads V1-V4 is having an MI in which location?', '["Anterior/Septal (LAD)", "Inferior (RCA)", "Lateral (LCx)", "Posterior"]'::jsonb, 0, 'V1-V4 view the front and septum of the heart.'),
        ('In clinical reasoning, the \"Law of Parsimony\" (Occam''s Razor) suggests:', '["One patient can have many diseases", "The simplest explanation is usually the correct one", "Always use the most complex test", "Never trust the lab"]'::jsonb, 1, 'Try to find one diagnosis that explains all the findings.'),
        ('A patient with "lower extremity swelling" that is "unilateral" and "tender" is a "horses" case for:', '["Heart failure", "DVT (Deep Vein Thrombosis)", "Lymphedema", "Cirrhosis"]'::jsonb, 1, 'Unilateral symptoms suggest a local (e.g., clot) rather than systemic (e.g., heart) problem.'),
        ('In a patient with "altered mental status," what is the most important "immediate" lab test after glucose?', '["Head CT", "ABG/VBG to check for CO2 narcosis or hypoxia", "Liver enzymes", "CBC"]'::jsonb, 1, 'Hypercapnia (high CO2) is a very common cause of somnolence and confusion.'),
        ('Which cognitive bias involves the clinician being more likely to diagnose a disease that they have "just read about"?', '["Availability bias", "Representativeness bias", "Anchoring", "Confirmation bias"]'::jsonb, 0, 'Recent information is the most \"available\" in the mind.'),
        ('A patient with "chest pain" that is relieved by "nitroglycerin" but has "normal" troponins likely has:', '["Myocardial Infarction", "Stable or Unstable Angina", "GERD", "Muscular strain"]'::jsonb, 1, 'Nitroglycerin relief suggests ischemia, but the lack of troponin rise means no permanent necrosis (yet).'),
        ('According to the "On Call" approach, a patient with "hypotension" and "fever" should be given:', '["Oral antibiotics", "Immediate IV fluid bolus and broad-spectrum antibiotics", "A cooling blanket", "Repeat BP in 1 hour"]'::jsonb, 1, 'The priority is stabilizing the \"tank\" and treating the source in suspected sepsis.'),
        ('Which cognitive bias involves the clinician \"downplaying\" the severity of a patient''s condition because the clinician is tired (end of shift)?', '["Omission bias", "Commission bias", "Availability bias", "Affective bias"]'::jsonb, 0, 'Fatigue leads to the \"let''s just wait\" mentality.'),
        ('A patient with "acute abdominal pain" and "shoulder pain" likely has:', '["Shoulder injury", "Diaphragmatic irritation (Kehr sign) from blood or air in the peritoneum", "Heart attack", "Anxiety"]'::jsonb, 1, 'Referred pain to the shoulder is a classic sign of diaphragmatic irritation.'),
        ('A patient with "anemia" and "neurological symptoms" (loss of vibration/position sense) likely has:', '["Iron deficiency", "Vitamin B12 deficiency", "Folate deficiency", "Anemia of chronic disease"]'::jsonb, 1, 'B12 deficiency causes \"subacute combined degeneration\" of the spinal cord.'),
        ('Which cognitive bias involves the clinician "ignoring" a patient''s request for an MRI because \"they don''t need it\"?', '["Authority bias", "Omission bias", "Framing", "Blind spot bias"]'::jsonb, 1, 'Paternalistic omission of information or testing.'),
        ('In clinical reasoning, \"System 1\" is primarily based on:', '["Mathematical logic", "Pattern recognition", "Slow checking", "Guidelines"]'::jsonb, 1, 'It is our \"intuition\" based on years of experience.'),
        ('Which physical exam maneuver for a \"shoulder dislocation\" involves checking for loss of the normal \"rounded\" contour?', '["Apprehension test", "Visual inspection for \"squared-off\" shoulder", "Neer test", "Hawkins test"]'::jsonb, 1, 'Loss of the deltoid curve is a classic sign of an anterior dislocation.'),
        ('A patient with "syncope" that occurs when they "look up" or "turn their head" likely has:', '["Vasovagal syncope", "Vertebrobasilar insufficiency", "Seizure", "Migraine"]'::jsonb, 1, 'Mechanical obstruction of the vertebral arteries can lead to transient brainstem ischemia.'),
        ('Which cognitive bias involves the clinician \"believing\" a test result is correct simply because it came from a \"high-tech\" machine?', '["Technology bias", "Authority bias", "Anchoring", "Framing"]'::jsonb, 0, 'Blindly trusting automated results over clinical assessment.'),
        ('A patient with "polyuria" and "low serum osmolality" (< 280) has evidence of:', '["Diabetes Insipidus", "Primary Polydipsia (excessive drinking)", "SIADH", "Normal"]'::jsonb, 1, 'The body is appropriately dumping excess water in the urine.'),
        ('According to "Bates," which physical exam sign is most specific for \"Chronic Liver Disease\"?', '["Jaundice", "Spider angiomata and Palmar erythema", "Fever", "Cough"]'::jsonb, 1, 'These vascular changes reflect high estrogen levels in cirrhosis.'),
        ('Which cognitive bias involves the clinician being influenced by the "first" piece of information they receive (e.g., a triage note)?', '["Confirmation bias", "Anchoring bias", "Availability bias", "Sunk cost"]'::jsonb, 1, 'Anchoring prevents the clinician from adjusting their diagnosis as new data arrives.'),
        ('A patient with "sudden" shortness of breath and "decreased breath sounds" on one side after a trauma has:', '["Pneumonia", "Pneumothorax", "Asthma", "Heart failure"]'::jsonb, 1, 'Acute traumatic collapse of the lung.')
    ) AS t(question, options, correct_index, explanation)
    WHERE NOT EXISTS (
        SELECT 1 FROM mcqs m 
        WHERE m.topic_id = v_topic_id 
        AND m.question = t.question
    );

    RAISE NOTICE 'SUCCESS: Batch 3 (MCQs 551-650) processed idempotently with fixed JSON syntax.';
END $$;

COMMIT;
